5	@custom-variant dark (&:is(.dark *));
6	
7	@theme inline {
8	  --color-background: var(--background);
9	  --color-foreground: var(--foreground);
10	
11	  /* RoobertPRO font */
12	  --font-roobert: var(--font-roobert);
13	  --font-sans: var(--font-roobert);
14	  --font-mono: var(--font-roobert);
15	  --font-heading: var(--font-roobert);
16	
17	  /* Boldteq Brand Colors */
18	  --color-brand-navy: #092245;
19	  --color-brand-navy-deep: #082753;
20	  --color-brand-cyan: #21cfff;
21	  --color-brand-blue: #019ae6;
22	  --color-brand-yellow: #FFEB85;
23	  --color-brand-dark: #111827;
24	  --color-brand-dark-alt: #1a1925;
25	  --color-brand-green: #3c7c43;
26	  --color-brand-green-badge: #18c958;
27	  --color-brand-light-blue: #ecf7fd;
28	  --color-brand-light-bg: #f5f7fa;
29	  --color-brand-gray-bg: #f7f7f8;
30	  --color-brand-card-hover: #cdebfa;
31	  --color-brand-card-border: #009ce0;
32	
33	  /* shadcn semantic tokens */
34	  --color-sidebar-ring: var(--sidebar-ring);
35	  --color-sidebar-border: var(--sidebar-border);
36	  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
37	  --color-sidebar-accent: var(--sidebar-accent);
38	  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
39	  --color-sidebar-primary: var(--sidebar-primary);
40	  --color-sidebar-foreground: var(--sidebar-foreground);
41	  --color-sidebar: var(--sidebar);
42	  --color-chart-5: var(--chart-5);
43	  --color-chart-4: var(--chart-4);
44	  --color-chart-3: var(--chart-3);
45	  --color-chart-2: var(--chart-2);
46	  --color-chart-1: var(--chart-1);
47	  --color-ring: var(--ring);
48	  --color-input: var(--input);
49	  --color-border: var(--border);
50	  --color-destructive: var(--destructive);
51	  --color-accent-foreground: var(--accent-foreground);
52	  --color-accent: var(--accent);
53	  --color-muted-foreground: var(--muted-foreground);
54	  --color-muted: var(--muted);
55	  --color-secondary-foreground: var(--secondary-foreground);
56	  --color-secondary: var(--secondary);
57	  --color-primary-foreground: var(--primary-foreground);
58	  --color-primary: var(--primary);
59	  --color-popover-foreground: var(--popover-foreground);
60	  --color-popover: var(--popover);
61	  --color-card-foreground: var(--card-foreground);
62	  --color-card: var(--card);
63	  --radius-sm: calc(var(--radius) * 0.6);
64	  --radius-md: calc(var(--radius) * 0.8);
65	  --radius-lg: var(--radius);
66	  --radius-xl: calc(var(--radius) * 1.4);
67	  --radius-2xl: calc(var(--radius) * 1.8);
68	  --radius-3xl: calc(var(--radius) * 2.2);
69	  --radius-4xl: calc(var(--radius) * 2.6);
