1	import type { Metadata } from "next";
2	import { SITE_CONFIG } from "@/lib/constants/site";
3	
4	export function createMetadata({
5	  title,
6	  description,
7	  path = "",
8	  ogImage,
9	}: {
10	  title: string;
11	  description: string;
12	  path?: string;
13	  ogImage?: string;
14	}): Metadata {
15	  const url = `${SITE_CONFIG.url}${path}`;
16	
17	  return {
18	    title,
19	    description,
20	    alternates: {
21	      canonical: url,
22	    },
23	    openGraph: {
24	      title,
25	      description,
26	      url,
27	      siteName: SITE_CONFIG.name,
28	      type: "website",
29	      ...(ogImage && {
30	        images: [{ url: ogImage, width: 1200, height: 630 }],
31	      }),
32	    },
33	    twitter: {
34	      card: "summary_large_image",
35	      title,
36	      description,
37	      ...(ogImage && { images: [ogImage] }),
38	    },
39	  };
40	}
