/* ============================================================
   CONTACT HERO — contact-hero.module.css
   ============================================================ */

.section {
  background-color: #fff;
  background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
  background-position: 50% 100%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: cover, auto;
  padding-top: 4rem;
  padding-bottom: 4rem;
  position: relative;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

.inner {
  text-align: center;
  max-width: 60rem;
  margin-left: auto;
  margin-right: auto;
}

/* Badge */
.badgeRow {
  justify-content: center;
  align-items: center;
  display: flex;
  margin-bottom: 1.5rem;
}

.badge {
  background-color: #21cfff12;
  border: 1px solid #05bafe;
  border-radius: 20px;
  padding: 0 13px;
  line-height: 32px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-weight: 500;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Heading */
.heading {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 50px;
  font-weight: 700;
  line-height: 1.2;
  margin-top: 0;
  margin-bottom: 1rem;
}

/* Subtitle */
.subtitle {
  color: #2b2b2b;
  max-width: 48rem;
  margin-left: auto;
  margin-right: auto;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin-bottom: 0;
}

/* Gradient fade at bottom */
.gradientFade {
  background-image: linear-gradient(#fff0, #fff);
  height: 120px;
  position: absolute;
  inset: auto 0 0;
  pointer-events: none;
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .heading {
    font-size: 36px;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    background-image: linear-gradient(#019ae614, #fff);
    background-position: 0 0;
    background-repeat: repeat;
    background-size: auto;
    padding-top: 3rem;
    padding-bottom: 2.5rem;
  }

  .container {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .heading {
    font-size: 1.75rem;
    line-height: 1.25;
  }

  .subtitle {
    font-size: 1rem;
  }
}

import styles from "./contact-hero.module.css";

export function ContactHero() {
  return (
    <div className={styles["section"]}>
      <div className={styles["container"]}>
        <div className={styles["inner"]}>
          {/* Badge */}
          <div className={styles["badgeRow"]}>
            <div className={styles["badge"]}>
              <p className={styles["badgeText"]}>Get In Touch</p>
            </div>
          </div>

          {/* Heading */}
          <h1 className={styles["heading"]}>Need any help? Contact us</h1>

          {/* Subtitle */}
          <p className={styles["subtitle"]}>
            Full-service agency crafting digital experiences that leave a lasting
            impression.
          </p>
        </div>
      </div>

      <div className={styles["gradientFade"]} />
    </div>
  );
}

/* ============================================================
   CONTACT INFO CARDS — contact-info-cards.module.css
   ============================================================ */

.section {
  background-color: #fff;
  padding: 0 5% 80px;
}

.container {
  width: 100%;
  max-width: 1100px;
  margin-left: auto;
  margin-right: auto;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-column-gap: 24px;
  grid-row-gap: 24px;
}

/* Card */
.card {
  background-color: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 16px;
  padding: 32px 28px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
  transition: background-color 0.3s, border-color 0.4s, box-shadow 0.3s;
}

.card:hover {
  background-color: #cdebfa;
  border-color: #009ce0;
  box-shadow: 0 4px 20px rgba(1, 154, 230, 0.1);
}

.iconWrap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background-color: #ecf7fd;
  flex-shrink: 0;
}

.cardDept {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
  margin: 0;
}

.cardEmail {
  color: #019ae6;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.4;
  text-decoration: none;
  display: block;
}

.cardEmail:hover {
  text-decoration: underline;
}

.cardFooter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 8px;
  border-top: 1px solid #e5e7eb;
}

.arrowLink {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: color 0.15s;
}

.arrowLink:hover {
  color: #019ae6;
}

.arrowIcon {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .grid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
  }
}

