const CARDS: ContactCard[] = [
  {
    dept: "Sales",
    email: "sales@boldteq.com",
    description: "For new agency partnerships, pricing, and subscription enquiries.",
    icon: <MailIcon />,
  },
  {
    dept: "Support",
    email: "support@boldteq.com",
    description: "For active clients needing help with delivery, tools, or access.",
    icon: <HeadphonesIcon />,
  },
  {
    dept: "Career",
    email: "hr@boldteq.com",
    description: "Interested in joining the Boldteq team? We'd love to hear from you.",
    icon: <BriefcaseIcon />,
  },
];

export function ContactInfoCards() {
  return (
    <section className={styles["section"]}>
      <div className={styles["container"]}>
        <div className={styles["grid"]}>
          {CARDS.map((card) => (
            <div key={card.dept} className={styles["card"]}>
              <div className={styles["iconWrap"]}>{card.icon}</div>
              <div>
                <h3 className={styles["cardDept"]}>{card.dept}</h3>
                <p
                  style={{
                    color: "#4b5563",
                    fontFamily: "'Roobert PRO', Arial, sans-serif",
                    fontSize: "14px",
                    lineHeight: "22px",
                    margin: "6px 0 10px",
                  }}
                >
                  {card.description}
                </p>
                <a
                  href={`mailto:${card.email}`}
                  className={styles["cardEmail"]}
                >
                  {card.email}
                </a>
              </div>
              <div className={styles["cardFooter"]}>
                <a
                  href={`mailto:${card.email}`}
                  className={styles["arrowLink"]}
                >
                  Send email
                  <span className={styles["arrowIcon"]}>
                    <ArrowRightIcon />
                  </span>
                </a>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

