"use client";

import { useState } from "react";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import styles from "./contact-form-section.module.css";

type FormStatus = "idle" | "submitting" | "success" | "error";

type FormFields = {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  service: string;
  message: string;
};

const INITIAL_FIELDS: FormFields = {
  firstName: "",
  lastName: "",
  email: "",
  phone: "",
  service: "",
  message: "",
};

const SERVICE_OPTIONS = [
  { value: "", label: "Select a service..." },
  { value: "web-development", label: "Web Development" },
  { value: "ui-ux-design", label: "UI/UX Design" },
  { value: "graphic-design", label: "Graphic Design" },
  { value: "app-development", label: "App Development" },
  { value: "other", label: "Other" },
];

function CheckCircleIcon() {
  return (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      style={{ flexShrink: 0 }}
    >
      <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
      <path d="m9 11 3 3L22 4" />
    </svg>
  );
}

function AlertCircleIcon() {
  return (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      style={{ flexShrink: 0 }}
    >
      <circle cx="12" cy="12" r="10" />
      <line x1="12" x2="12" y1="8" y2="12" />
      <line x1="12" x2="12.01" y1="16" y2="16" />
    </svg>
  );
}

export function ContactFormSection() {
  const [fields, setFields] = useState<FormFields>(INITIAL_FIELDS);
  const [status, setStatus] = useState<FormStatus>("idle");

  function handleChange(
    e: React.ChangeEvent<
      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    >
  ) {
    const { name, value } = e.target;
    setFields((prev) => ({ ...prev, [name]: value }));
  }

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (status === "submitting") return;

    setStatus("submitting");

    try {
      // TODO: integrate with API route
      console.log("Contact form submission:", fields);
      // Simulate async work
      await new Promise<void>((resolve) => setTimeout(resolve, 800));
      setStatus("success");
      setFields(INITIAL_FIELDS);
    } catch {
      setStatus("error");
    }
  }

  if (status === "success") {
    return (
      <section className={styles["section"]}>
        <div className={styles["container"]}>
          <h2 className={styles["heading"]}>Send us a message.</h2>
          <div className={styles["successMsg"]}>
            <CheckCircleIcon />
            Thank you! Your submission has been received!
          </div>
        </div>
      </section>
    );
  }

  return (
    <section className={styles["section"]}>
      <div className={styles["container"]}>
        <h2 className={styles["heading"]}>Send us a message.</h2>

        <form onSubmit={handleSubmit} className={styles["form"]} noValidate>
          {/* First Name + Last Name */}
          <div className={styles["rowTwo"]}>
            <div className={styles["field"]}>
              <label htmlFor="firstName" className={styles["label"]}>
                First Name
              </label>
              <Input
                id="firstName"
                name="firstName"
                type="text"
                placeholder="Jane"
                value={fields.firstName}
                onChange={handleChange}
                required
                className={styles["input"]}
              />
            </div>
            <div className={styles["field"]}>
              <label htmlFor="lastName" className={styles["label"]}>
                Last Name
              </label>
              <Input
                id="lastName"
                name="lastName"
                type="text"
                placeholder="Smith"
                value={fields.lastName}
                onChange={handleChange}
                required
                className={styles["input"]}
              />
            </div>
          </div>

          {/* Email */}
          <div className={styles["field"]}>
            <label htmlFor="email" className={styles["label"]}>
              Email
            </label>
            <Input
              id="email"
              name="email"
              type="email"
              placeholder="jane@agency.com"
              value={fields.email}
              onChange={handleChange}
              required
              className={styles["input"]}
            />
          </div>

          {/* Phone */}
          <div className={styles["field"]}>
            <label htmlFor="phone" className={styles["label"]}>
              Phone
            </label>
            <Input
              id="phone"
              name="phone"
              type="tel"
              placeholder="+1 (555) 000-0000"
              value={fields.phone}
              onChange={handleChange}
              className={styles["input"]}
            />
          </div>

          {/* Service */}
          <div className={styles["field"]}>
            <label htmlFor="service" className={styles["label"]}>
              Service
            </label>
            <select
              id="service"
              name="service"
              value={fields.service}
              onChange={handleChange}
              className={styles["select"]}
            >
              {SERVICE_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>

          {/* Message */}
          <div className={styles["field"]}>
            <label htmlFor="message" className={styles["label"]}>
              Message
            </label>
            <Textarea
              id="message"
              name="message"
              placeholder="Tell us about your project..."
              value={fields.message}
              onChange={handleChange}
              required
              className={styles["textarea"]}
            />
          </div>

          {/* Error */}
          {status === "error" && (
            <div className={styles["errorMsg"]}>
              <AlertCircleIcon />
              Oops! Something went wrong. Please try again or email us directly.
            </div>
          )}

          {/* Submit */}
          <button
            type="submit"
            className={styles["submitBtn"]}
            disabled={status === "submitting"}
          >
            {status === "submitting" ? "Sending…" : "Send Your Message"}
          </button>
        </form>
      </div>
    </section>
  );
}

